/** Real request-router + auth/owner gates over owned loopback HTTP and disk WAL. */
import assert from 'node:assert/strict';import{mkdirSync,writeFileSync}from'node:fs';import{join}from'node:path';import{performance,monitorEventLoopDelay}from'node:perf_hooks';
import{initDatabase,getDb,closeDatabase}from'../../src/db/connection.js';
import{createUser,updateUser}from'../../src/db/users.js';import{createWebSession,revokeUserWebSessions}from'../../src/db/web-sessions.js';
import{storeChatMetadata}from'../../src/db/messages.js';import{provisionUserHome}from'../../src/db/session-ownership.js';
import{RequestRouterService}from'../../src/channels/web/request-router-service.js';import{WebAuthGateway}from'../../src/channels/web/auth/auth-gateway.js';
import{WebauthnChallengeTracker}from'../../src/channels/web/auth/webauthn-challenges.js';import{TotpFailureTracker}from'../../src/channels/web/auth/totp-failure-tracker.js';
import{getTimelineResponse}from'../../src/channels/web/timeline-service.js';import{assertPathWithinTestFilesystemIsolation}from'../../scripts/test-filesystem-isolation.js';
const mode=process.argv[2],instrument=process.argv[3]==='instrument';assert(['single-user','family-shared'].includes(mode));
const workspace=process.env.PICLAW_WORKSPACE!;assertPathWithinTestFilesystemIsolation(workspace,process.env,{allowRoot:false});assert.equal(process.env.PICLAW_DB_IN_MEMORY,'0');
mkdirSync(join(workspace,'.piclaw'),{recursive:true});writeFileSync(join(workspace,'.piclaw/config.json'),JSON.stringify({domains:{access:{mode}}}));
initDatabase();const db=getDb(),owners:string[]=[],chats:string[]=[],tokens:string[]=[];
for(let n=0;n<2;n++){const user=mode==='family-shared'?createUser(db,{username:'synthetic-'+n,displayName:'Synthetic '+n}).id:'default';const chat='web:http-synthetic-'+n;owners.push(user);chats.push(chat);tokens.push('synthetic-http-cookie-'+n);storeChatMetadata(chat,'2026-01-01T00:00:00Z');if(mode==='family-shared'){provisionUserHome(db,user,chat);updateUser(db,user,{enabled:true});}createWebSession(tokens[n],user,3600,'totp');}
db.transaction(()=>{const q=db.prepare('INSERT INTO messages(id,chat_jid,sender,sender_name,content,timestamp,is_from_me,is_bot_message)VALUES(?,?,?,?,?,?,?,?)');for(let n=0;n<10000;n++)q.run('http-profile-'+n,chats[n%2],'synthetic','Synthetic','Synthetic owned row '+n,new Date(1700000000000+n).toISOString(),0,0)}).immediate();
const json=(body:unknown,status=200)=>Response.json(body,{status});const gateway=new WebAuthGateway({accessMode:mode as any,passkeyMode:'',totpSecret:'synthetic-fixture-auth',internalSecret:'',sessionTtlSeconds:3600,hasTls:false},{json,challenges:new WebauthnChallengeTracker(),failureTracker:new TotpFailureTracker()});
const channel={authGateway:gateway,json,endpointContexts:{auth:()=>({})},clampInt:(value:string|null,fallback:number,min:number,max:number)=>value&&Number.isFinite(Number(value))?Math.max(min,Math.min(max,Math.trunc(Number(value)))):fallback,parseOptionalInt:(value:string|null)=>value&&Number.isSafeInteger(Number(value))?Number(value):null,handleTimeline:(limit:number,before?:number,chat?:string)=>{const r=getTimelineResponse(chat||chats[0],limit,before);return json(r.body,r.status)},serveStatic:()=>{throw Error('no assets expected')}}as any;
const router=new RequestRouterService(channel,mode as any),server=Bun.serve({hostname:'127.0.0.1',port:0,fetch:req=>router.handle(req)});
const originalFetch=globalThis.fetch;let external=0;globalThis.fetch=Object.assign(async(input:any,init:any)=>{const url=new URL(typeof input==='string'?input:input instanceof URL?input.href:input.url);if(url.origin!==server.url.origin){external++;throw Error('external network denied')}return originalFetch(input,init)},{preconnect:()=>{external++;throw Error('preconnect denied')}})as typeof fetch;
const parse=JSON.parse,stringify=JSON.stringify,query=db.query,prepare=db.prepare,metrics:Record<string,{calls:number;ms:number}>={};const entry=(key:string)=>metrics[key]??={calls:0,ms:0};
const timed=<T>(key:string,fn:()=>T)=>{const start=performance.now();try{return fn()}finally{entry(key).calls++;entry(key).ms+=performance.now()-start}};
const proxies=new WeakMap<object,object>();const wrap=(s:any)=>{const previous=proxies.get(s);if(previous)return previous;const p=new Proxy(s,{get(t,k){if(!['get','all','run'].includes(String(k)))return Reflect.get(t,k,t);return(...args:unknown[])=>timed('SQL.'+String(k),()=>Reflect.apply(t[k],t,args))}});proxies.set(s,p);return p};
if(instrument){db.query=((...a:Parameters<typeof query>)=>wrap(timed('SQL.query',()=>Reflect.apply(query,db,a))))as typeof query;db.prepare=((...a:Parameters<typeof prepare>)=>wrap(timed('SQL.prepare',()=>Reflect.apply(prepare,db,a))))as typeof prepare;JSON.parse=((...a:Parameters<typeof parse>)=>timed('JSON.parse',()=>parse(...a)))as typeof parse;JSON.stringify=((...a:Parameters<typeof stringify>)=>timed('JSON.stringify',()=>stringify(...a)))as typeof stringify;}
const loops=monitorEventLoopDelay({resolution:1});loops.enable();const batches:number[]=[],responseBytes:number[]=[],cpu=process.cpuUsage(),start=performance.now();
try{
 for(let batch=0;batch<25;batch++){const at=performance.now();await Promise.all(Array.from({length:4},async(_,slot)=>{const owner=(batch+slot)%2,foreign=mode==='family-shared'&&slot===3;const chat=chats[foreign?1-owner:owner],response=await fetch(new URL('/timeline?limit=50&chat_jid='+chat,server.url),{headers:{cookie:'piclaw_session='+tokens[owner]}});assert.equal(response.status,foreign?403:200);assert(response.headers.has('x-request-id'));if(mode==='family-shared')assert.equal(response.headers.get('cache-control'),'private, no-store');const body=await response.text();responseBytes.push(Buffer.byteLength(body));const parsed=JSON.parse(body);if(foreign){assert.deepEqual(parsed,{error:'Session access denied.'});assert(!body.includes('Synthetic owned row'))}else{assert.equal(parsed.posts.length,50);assert(parsed.posts.every((row:any)=>row.chat_jid===chat));}}));batches.push(performance.now()-at);await Bun.sleep(5);}
 revokeUserWebSessions(owners[0]);const denied=await fetch(new URL('/timeline?chat_jid='+chats[0],server.url),{redirect:'manual',headers:{cookie:'piclaw_session='+tokens[0]}});assert([401,302].includes(denied.status));await denied.body?.cancel();assert.equal(external,0);await Bun.sleep(10);loops.disable();console.log(stringify({mode,instrument,runtime:Bun.version,requests:100,concurrency:4,batches,wallMs:performance.now()-start,cpu:process.cpuUsage(cpu),responseBytesTotal:responseBytes.reduce((n,x)=>n+x,0),metrics:instrument?metrics:null,eventLoop:{samples:loops.count,maxMs:loops.max/1e6,meanMs:loops.mean/1e6},memory:process.memoryUsage(),revokedRequestDenied:true,foreignRequestsDenied:mode==='family-shared'?25:0,external,settings:{journal:db.query('PRAGMA journal_mode').get(),synchronous:db.query('PRAGMA synchronous').get()},scope:'Actual owned loopback HTTP server/request router/auth gateway plus authorised timeline queries and family denials; request-id and family cache-control asserted, not every security header. 100 measured requests plus one serial revocation probe; wall/CPU include sleeps and revocation, exclude startup/seed. External whole-child CPU profile includes startup/seed. Synthetic10krows/two users; single-user100successes, family75successes25denials, not comparable speedups. No message writes/login/SSE/browser/contending writer/provider. Wrapped fetch denies non-server origin after setup; not a universal network sandbox.'}));
}finally{loops.disable();db.query=query;db.prepare=prepare;JSON.parse=parse;JSON.stringify=stringify;globalThis.fetch=originalFetch;try{server.stop(true)}finally{closeDatabase()}}
